from functools import lru_cache

@lru_cache
def count_neq_numbers_with_prefix(maxi, no):
    if maxi < 10:
        return maxi - (0 < no <= maxi)
    q = maxi // 10
    r = maxi % 10
    ans = 0
    for x in range(10):
        if x == no:
            continue
        if x <= r:
            ans += count_neq_numbers_with_prefix(q, x)
        else:
            ans += count_neq_numbers_with_prefix(q - 1, x)
    return ans

def count_neq_numbers(maxi):
